// Paned — Gtk.Paned
//
// Generated by bin/11-generate-components, which does not overwrite.
//
// It ships no template, so the markup is the one element its CSS node is, carrying what
  // Adwaita styles paned with.

import type { ReactNode } from "react"

import { cn } from "@/lib/utils"
import type { WidgetProps } from "@/lib/widget-props"

export interface PanedProps extends WidgetProps {
  className?: string
  children?: ReactNode
  /** Widget, from Gtk.Paned */
  endChild?: ReactNode

  /** gint, from Gtk.Paned */
  position?: number

  /** gboolean, from Gtk.Paned */
  positionSet?: boolean

  /** gboolean, from Gtk.Paned */
  resizeEndChild?: boolean

  /** gboolean, from Gtk.Paned */
  resizeStartChild?: boolean

  /** gboolean, from Gtk.Paned */
  shrinkEndChild?: boolean

  /** gboolean, from Gtk.Paned */
  shrinkStartChild?: boolean

  /** Widget, from Gtk.Paned */
  startChild?: ReactNode

  /** gboolean, from Gtk.Paned */
  wideHandle?: boolean
}

export function Paned({ className, children }: PanedProps) {
  return (
    <div className={cn(className)}>
      {children}
    </div>
  )
}
